/**
 * Cascade behind removing a member: every issue assigned to them, in this org,
 * loses its assignee. Applied regardless of archive state, so a departed
 * member's name does not linger as the assignee of a since-archived issue.
 */
export async function unassignIssuesForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set({ assigneeId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.assigneeId, userId)))
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

