  const now = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // A current member accepting a stray invitation is a no-op for them: the
  // invitation is still used up so it cannot be replayed, but their role and
  // seat are untouched.
  if (existing && isActiveMember(existing)) {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      now,
    );
    return existing;
  }

  // A former member is re-admitted on the membership row the org already had
  // for them, rather than a fresh one, so whatever was recorded against it
  // before they left stays attached.
  const member = existing
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        now,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    now,
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

